SourceCode.Declaration:
/// <summary>
/// Data contract class holding the parameters for file upload to Azure file share
/// </summary>
[DataContract]
class OMGOutboundDataContract_AzureFileShare extends OMGOutboundDataContract_Azure
{   
    OMGFileShareName        fileShareName;
    OMGTargetDirectory      targetDirectory;

}

Method.Source:
[DataMember, OMGAzureFileShareName, SysOperationDisplayOrder('3')]
public OMGFileShareName parmFileShareName(OMGFileShareName _fileShareName = fileShareName)
{
    fileShareName = _fileShareName;
    return fileShareName;
}

[DataMember, OMGAzureFileShareDirectory, SysOperationDisplayOrder('4')]
public OMGTargetDirectory parmTargetDirectory(OMGTargetDirectory _targetDirectory = targetDirectory)
{
    targetDirectory = _targetDirectory;
    return targetDirectory;
}

/// <summary>
/// The caption used on the dialog
/// </summary>
/// <returns>A descriptive text</returns>
public Description dialogCaption()
{
    return "@OMG:ExportToAzureFileShares";
}
